import numpy as np

def l2_norm(x):
    return float(np.linalg.norm(x))

def cosine_similarity(a, b):
    na, nb = l2_norm(a), l2_norm(b)
    if na == 0 or nb == 0:
        return None
    return float(np.dot(a, b) / (na * nb))

samples = {
    'network_A': np.array([120.0, 35.0, 0.02]),
    'network_B': np.array([110.0, 40.0, 0.03]),
    'network_C': np.array([20.0, 95.0, 0.40])
}

for name, vec in samples.items():
    print(name, 'norm=', round(l2_norm(vec), 4))

print('cos(A,B)=', cosine_similarity(samples['network_A'], samples['network_B']))
print('cos(A,C)=', cosine_similarity(samples['network_A'], samples['network_C']))
